#!/bin/sh
# Regera os scripts de colar no SQL Editor (um único comando cada; ver scripts/build-editor-release.mjs).
set -e
cd "$(dirname "$0")/.."
node scripts/build-editor-release.mjs 34_ai_balance.sql supabase/releases/ia_equilibrio.sql 'public.mgr_hub_before_v33()' 'public.cw_foreign_hiring(text,date)' 'equilíbrio da IA ativo' 'Requer a evolução 33 (supabase/releases/mensagens.sql)'
node scripts/build-editor-release.mjs 35_update_gift.sql supabase/releases/presentes_atualizacao.sql 'public.cw_foreign_hiring(text,date)' 'public.release_gift_claim()' 'presentes da atualização e avatares ativos' 'Requer a evolução 34 (supabase/releases/ia_equilibrio.sql)'
node scripts/build-editor-release.mjs 36_first_access_speed.sql supabase/releases/primeiro_acesso_rapido.sql 'public.cw_initialize_finances(uuid)' 'public.cw_initialize_finances(uuid)' 'primeiro acesso ao modo Temporadas mais rápido' 'Requer o modo Temporadas com mundo paralelo (evolução 26 ou supabase/releases/carreira_completa.sql)'
node scripts/build-editor-release.mjs 37_economy_market_fixes.sql supabase/releases/mercado_economia.sql 'public.cw_initialize_finances(uuid)' 'public.cw_market_tick_before_v37(uuid)' 'mercado, economia e notícias corrigidos' 'Requer o modo Temporadas com mundo paralelo (supabase/releases/carreira_completa.sql)' 'live'
node scripts/build-editor-release.mjs 38_storage_diet.sql supabase/releases/banco_enxuto.sql 'public.cw_settle_month(uuid,date)' 'public.cw_compact_month(uuid,date)' 'banco enxuto (salários da IA agrupados e dados auxiliares antigos removidos)' 'Requer o modo Temporadas com mundo paralelo (supabase/releases/carreira_completa.sql)' 'live'
node scripts/build-editor-release.mjs 39_squad_cash_window_storage.sql supabase/releases/elenco_caixa_janela.sql 'public.cw_compact_month(uuid,date)' 'public.cw_prune_career(uuid)' 'elenco, caixa, janela de transferências e banco menor' 'Requer a evolução 38 (supabase/releases/banco_enxuto.sql)' 'live'
node scripts/build-editor-release.mjs 40_realistic_negotiations.sql supabase/releases/negociacoes_realistas.sql 'public.cw_market_tick_before_v37(uuid)' 'public.cw_club_level(text)' 'negociações realistas e idade nas cartas' 'Requer a evolução 37 (supabase/releases/mercado_economia.sql)' 'live'
node scripts/build-editor-release.mjs 41_match_history_diet.sql supabase/releases/historico_enxuto.sql 'public.cw_prune_career(uuid)' 'public.cw_prune_career(uuid)' 'histórico de partidas enxuto e desempate por fair play corrigido' 'Requer a evolução 39 (supabase/releases/elenco_caixa_janela.sql)' 'live'
